/**
 * Raster brand assets, generated by `scripts/make-brand-rasters.mjs`.
 *
 * Open Graph, the RSS channel image and schema.org all require raster images
 * (PNG/JPEG/GIF) — `public/assets/brand/` otherwise holds only SVG. These
 * constants are the single source of truth for their paths, shared by
 * BaseLayout (og:image), utils/feed.ts (<channel><image>) and the post routes
 * (BlogPosting.image).
 */

/** Default 1200x630 share card, used by any page that passes no image. */
export const OG_IMAGE = {
  path: "/assets/brand/og-default.png",
  width: 1200,
  height: 630,
  alt: "unfolding with Peg — Peggy Pei-Chun Hsieh 謝佩君, learning experience design",
} as const;

/** Feed avatar. The RSS spec caps <channel><image> at 144px wide. */
export const FEED_IMAGE = {
  path: "/assets/brand/feed-image.png",
  width: 144,
  height: 144,
} as const;
